package dev.zomboidmelee.boxing;
import java.util.*;
/** The heel lands nine server ticks after commitment. No damage or hit sound on wind-up. */
public final class Stomp21{
 record Pending(int id,UUID uuid,Object dimension,long at){}
 static final Map<Object,Pending>PENDING=new WeakHashMap<>();
 static boolean player(Object p){return R.type("net.minecraft.server.level.ServerPlayer").isInstance(p)&&Boxing16.empty(p)&&R.yes(R.call(p,"isAlive"))&&!R.yes(R.call(p,"isSpectator"))&&!R.yes(R.call(p,"isSleeping"))&&!R.yes(R.call(p,"isUsingItem"));}
 static Object dimension(Object p){return R.call(R.call(p,"level"),"dimension");}
 public static void request(Object p,int id){if(PENDING.containsKey(p))return;if(!player(p)||Combat18.time(p)<Combat18.NEXT.getOrDefault(p,Long.MIN_VALUE)){Net20.cue(p,20);return;}Object v=R.call(R.call(p,"level"),"getEntity",id);if(!target(p,v)){Net20.cue(p,20);return;}if(!R.yes(R.call(R.type("com.armilp.ezweight.stamina.StaminaCommon"),"consume",p,100d))){Server20.exhausted(p);return;}long now=Combat18.time(p);PENDING.put(p,new Pending(id,(UUID)R.call(v,"getUUID"),dimension(p),now+9));Combat18.NEXT.put(p,now+20);Net20.cue(p,12);}
 static boolean target(Object p,Object v){return v!=null&&R.yes(R.call(v,"isAlive"))&&Stomp18.stompAim(p,v)&&R.yes(R.call(p,"hasLineOfSight",v));}
 public static void tick(Object event){Object p=R.call(event,"getEntity");if(!R.type("net.minecraft.server.level.ServerPlayer").isInstance(p)||R.yes(R.call(R.call(p,"level"),"isClientSide")))return;Pending pending=PENDING.get(p);if(pending==null)return;if(!player(p)||!Objects.equals(dimension(p),pending.dimension)){PENDING.remove(p);Net20.cue(p,20);return;}if(Combat18.time(p)<pending.at)return;PENDING.remove(p);Object v=R.call(R.call(p,"level"),"getEntity",pending.id);if(v==null||!pending.uuid.equals(R.call(v,"getUUID"))||!target(p,v)){Net20.cue(p,21);return;}land(p,v);}
 static void land(Object p,Object v){Server20.prepare(v);boolean head=Stomp18.headAim(p,v);int old=Stomp18.state(v);Object point=head?Stomp18.head(v):R.call(v,"position");if(head)R.call(Stomp18.GORE,"set",v,old|257);Object source=R.call(R.call(p,"damageSources"),"playerAttack",p);boolean applied;Combat18.ACTION.set(2);try{applied=R.yes(R.call(v,"hurt",source,head?Float.MAX_VALUE:10f));}finally{Combat18.ACTION.remove();}if(!applied){if(head)R.call(Stomp18.GORE,"set",v,old);Net20.cue(p,21);return;}Net20.cue(p,18);Combat18.sound(v,"PLAYER_ATTACK_STRONG",.95f,.60f);Combat18.sound(v,"SLIME_SQUISH",head?1f:.60f,head?.65f:.85f);Object state=R.call(R.get(R.type("net.minecraft.world.level.block.Blocks"),"REDSTONE_BLOCK"),"defaultBlockState"),option=R.make("net.minecraft.core.particles.BlockParticleOption",R.get(R.type("net.minecraft.core.particles.ParticleTypes"),"BLOCK"),state);R.call(R.call(v,"level"),"sendParticles",option,R.num(R.get(point,"x")),R.num(R.get(point,"y"))+(head?0:.20),R.num(R.get(point,"z")),head?32:10,.20,.10,.20,.075);}
}
